INSERT INTO `parks` (`id`, `slug`, `name`, `category`, `region`, `province`, `municipality`, `description`, `area_hectares`, `coastline_km`, `latitude`, `longitude`, `created_at`, `updated_at`) VALUES (1,'cabo-cope-puntas-calnegre','Cabo Cope y Puntas de Calnegre','Parque Regional','Región de Murcia','Murcia','Águilas y Lorca','Espacio litoral protegido con calas, acantilados, matorral semiárido y praderas marinas. Este parque es el piloto de NaturDex.',NULL,17.00,37.501600,-1.449250,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (1,1,'torre-cope','Torre de Cope','Cultural','Torre vigía costera del siglo XVI, construida para la defensa frente a la piratería berberisca que asolaba el litoral murciano. Catalogada como Bien de Interés Cultural. Junto a ella se levantó la Ermita de Cope, que daba servicio religioso a su guarnición.',37.436950,-1.484410,'Img/poi/torre-cope.jpg','OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Jose Lorca, dominio público); Región de Murcia Digital (CARM)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (2,1,'cabo-cope','Cabo Cope','Paisajístico','Promontorio litoral y mirador natural sobre la bahía de Mazarrón. El macizo calizo de Cabo Cope está catalogado como Lugar de Interés Geológico: en él aflora muy bien representado el Complejo Maláguide (calizas, micaesquistos y cuarcitas), con interés geomorfológico, estratigráfico y neotectónico, además de su interés cultural.',37.427932,-1.493014,'Img/poi/cabo-cope.jpg','Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: J.Alberto, CC BY-SA 4.0)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (3,1,'puntas-calnegre','Puntas de Calnegre','Paisajístico','Núcleo litoral en el extremo norte del parque, con playas, gravas, calas y vistas abiertas al Mediterráneo, en el tramo donde Lomo de Bas termina en el mar.',37.507796,-1.403058,'Img/poi/puntas-calnegre.jpg','OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Pau lopezca, CC BY-SA 3.0 ES); Región de Murcia Digital (CARM)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (4,1,'playa-calnegre','Playa de Calnegre','Paisajístico','Cala de arena y grava dentro del entorno protegido, punto de acceso habitual a la ruta litoral del GR-92 hacia Puntas de Calnegre.',37.506887,-1.416314,'Img/poi/playa-calnegre.jpg','OpenStreetMap contributors (ODbL); Wikimedia Commons (foto: Mueca, CC BY-SA 4.0)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (5,1,'cala-blanca','Cala Blanca','Geológico','Tramo costero de interés geomorfológico. Aquí afloran cuarcitas, micaesquistos, filitas y conglomerados triásicos del Complejo Alpujárride, visibles en los barrancos y el contacto con el mar.',37.483480,-1.462240,'https://commons.wikimedia.org/wiki/Special:FilePath/Cala_blanca_2.JPG','Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (6,1,'lomo-bas','Lomo de Bas','Geológico','Relieve interior que ayuda a leer el contraste entre las sierras litorales, las ramblas y la costa semiárida. Sus laderas suaves enlazan geomorfológicamente con la unidad de la Marina de Cope.',37.511086,-1.457429,'Img/poi/lomo-bas.jpg','Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM); Wikimedia Commons (foto: Mabelcalabuig, CC BY-SA 3.0 ES)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (7,1,'calabardina','Calabardina','Acceso','Núcleo costero de Águilas que funciona como puerta de entrada meridional al parque, al pie del macizo de Cabo Cope. En época púnica y romana funcionó como fondeadero protegido de los vientos de levante; la zona ha dado hallazgos continuos de ánforas de origen púnico y de todos los periodos romanos por su buen abrigo natural.',37.434520,-1.503470,'Img/poi/calabardina.jpg','Región de Murcia Digital (CARM) - Águilas, Yacimientos; Wikimedia Commons (foto: Rietje Swart, CC BY-SA 2.0)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (8,1,'playa-Charco','Playa del Charco','Natural','Playa con uno de los mejores tarayales (Tamarix) del litoral murciano; el PORN la cita por su bosque de tarais, representativo del hábitat de interés comunitario 92D0 (galerías y matorrales ribereños termomediterráneos).',37.449442,-1.482124,NULL,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021); OpenStreetMap contributors (ODbL)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (9,1,'ermita-cope','Ermita de Cope','Religioso','Ermita del siglo XVIII que daba servicio religioso a la guarnición de la Torre de Cope, junto a la que se levanta. Según la tradición local recogida en fuentes de turismo regional, fue destruida por un incendio provocado en un ataque pirata, salvándose solo la talla de la cabeza del Cristo, hoy muy venerada; este episodio concreto está pendiente de contrastar con una fuente documental primaria.',37.435630,-1.484840,'https://commons.wikimedia.org/wiki/Special:FilePath/Panor%C3%A1mica_de_la_Torre_de_Cope_y_el_Golfo_de_Mazarr%C3%B3n.jpg','OpenStreetMap contributors (ODbL); tradición oral recogida en fuentes de turismo regional (episodio del incendio pendiente de contrastar con fuente documental primaria)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (11,1,'dunas-fosiles-cope','Dunas fósiles de Cabo Cope','Geológico','Playas y dunas fósiles del Eutirreniense (Pleistoceno), formadas por calcarenitas de origen marino litoral muy erosionables por la acción del agua, que han originado numerosas oquedades y cavidades costeras. El Anexo I del proyecto de PORN las señala como uno de los valores geomorfológicos y paleogeográficos más singulares de la línea de costa del parque.',37.441423,-1.484144,'https://commons.wikimedia.org/wiki/Special:FilePath/Torre_de_Cope.JPG','Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM)',1,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (12,1,'yacimientos-garrobillo','Yacimientos paleontológicos de Garrobillo','Paleontológico','Garrobillo 1 y Garrobillo 2, parte de la Cuenca de Cope (Arco de Águilas, Zonas Internas Béticas). Garrobillo 1 muestra el contacto de los materiales neógenos con el basamento metamórfico bético; Garrobillo 2 conserva calcarenitas bioclásticas con concentraciones del foraminífero Lenticulina spp. y de pectínidos de origen tormentoso.',37.494000,-1.498000,NULL,'Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa del paraje El Garrobillo; las coordenadas exactas de cada yacimiento no están publicadas.',1,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (13,1,'yacimientos-cope-galera','Yacimientos paleontológicos de Galera-Cope','Paleontológico','Galera-1, Cope 1 y Cope 2, en el extremo sur de la Cuenca de Cope. Galera-1 documenta la transgresión pliocena mediante facies excepcionales de washover fans; Cope 1 y Cope 2, junto al saladar, aportan marcadores bioestratigráficos que sitúan temporalmente los eventos de la cuenca durante el Plioceno.',37.471473,-1.469368,'https://commons.wikimedia.org/wiki/Special:FilePath/Cabo_Cope_-_WLE_Spain_2015.jpg','Anexo I del proyecto de PORN del Parque Regional Calnegre y Cabo Cope (ANSE/CARM). Posición representativa junto al saladar y la Playa de la Galera; las coordenadas exactas de cada yacimiento no están publicadas.',1,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (14,1,'fuente-piratas','Fuente de los piratas','Natural','Ensenada de la Fuente, cala al este de Cabo Cope que toma su nombre de un manantial de agua dulce junto al que se levanta la Torre de Cope. Fue punto de aguada para la guarnición de la torre y, según la tradición oral recogida en fuentes de turismo regional, también lo usaban las embarcaciones berberiscas que hostigaban la costa (de ahí el nombre popular).',37.433713,-1.483251,'https://commons.wikimedia.org/wiki/Special:FilePath/Ensenada_de_la_Fuente.jpg','Wikipedia - \"Cabo Cope\"; descubriendomurcia.com; tradición oral recogida en fuentes de turismo regional (nombre popular pendiente de confirmar con fuente documental primaria)',1,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (15,1,'punta-cabricas','Punta de las Cabricas','Paisajístico','Saliente rocoso del litoral entre Cabo Cope y Calabardina, con acantilados característicos de este tramo costero del parque y buenas vistas hacia el macizo de Cope.',37.432940,-1.476930,'https://commons.wikimedia.org/wiki/Special:FilePath/Puntas_de_Calnegre%2C_desde_Piedras_Negras.JPG','OpenStreetMap contributors (ODbL)',0,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `points_of_interest` (`id`, `park_id`, `slug`, `name`, `type`, `description`, `latitude`, `longitude`, `image_url`, `source`, `is_approx`, `audio_url`, `audio_transcript`, `created_at`) VALUES (16,1,'ruinas-garrobillo','Ruinas de la aldea de El Garrobillo','Cultural','Restos de El Garrobillo, antigua pedanía agrícola del término de Lorca en la Marina de Cope, hoy despoblada. Junto a Ramonete, forma parte de los núcleos rurales tradicionales vinculados al aprovechamiento agrícola histórico de esta zona del parque.',37.492410,-1.499570,NULL,'OpenStreetMap contributors (ODbL) - topónimo \"El Garrobillo\"; referencias generales a las pedanías históricas de Ramonete y El Garrobillo en el término de Lorca. Ubicación aproximada (posición del paraje, no de una edificación concreta verificada en campo).',1,NULL,NULL,'2026-07-14 10:10:36');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (1,1,'Tortuga mora','Testudo graeca','fauna','Reptil','Matorral termomediterráneo semiárido','Amenazada','Reptil terrestre emblemático de ambientes áridos, matorrales mediterráneos y zonas abiertas del sureste ibérico.','Caparazón abombado; Actividad en horas templadas; No manipular ni desplazar ejemplares','Primavera y otoño','https://upload.wikimedia.org/wikipedia/commons/thumb/f/f8/Testudo_graeca_Lambert_01.jpg/640px-Testudo_graeca_Lambert_01.jpg',37.507500,-1.442200,5,1,'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre','Chordata','Reptilia','Testudines','Testudinidae','Testudo','VU A1cd (evaluación IUCN de 1996; pendiente de reevaluación global reciente)','Catálogo Español de Especies Amenazadas / LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)','Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (2,1,'Águila perdicera','Aquila fasciata','fauna','Ave rapaz','Cortados y áreas abiertas','Amenazada','Rapaz mediterránea asociada a sierras, cortados y territorios de campeo amplios.','Silueta grande y vuelo potente; Observar a distancia; Evitar molestias en zonas de nidificación','Todo el año','https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Bonellis_Eagle_Aquila_fasciata_by_Dr._Raju_Kasambe_DSCN1709_%2810%29.jpg/640px-Bonellis_Eagle_Aquila_fasciata_by_Dr._Raju_Kasambe_DSCN1709_%2810%29.jpg',37.520200,-1.426000,5,1,'Región de Murcia Digital (CARM) - Fauna de Cabo Cope y Puntas de Calnegre; Libro Rojo de las Aves de España, SEO/BirdLife 2004; Ley 7/1995, de 21 de abril, de la Fauna Silvestre de la Región de Murcia (Anexo I)','Chordata','Aves','Accipitriformes','Accipitridae','Aquila','LC (población global amplia en Asia y África pese al declive europeo)','Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021)','Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción (población reproductora muy reducida)',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
