INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (15,1,'Sabina negral','Juniperus phoenicea','flora','Arbusto o arbolillo','Matorral litoral y laderas secas','Interés botánico','Conífera mediterránea resistente a viento, sequía y suelos pobres, con poblaciones de interés en Cabo Cope.','Hojas escamosas; Frutos redondeados; Porte compacto','Todo el año','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Juniperus_phoenicea_001.JPG/640px-Juniperus_phoenicea_001.JPG',37.500100,-1.438400,4,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Wikipedia','Tracheophyta','Pinopsida','Pinales','Cupressaceae','Juniperus','LC','No catalogada en la Lista Roja de la Flora Vascular Española 2008','No incluida en el Catálogo Regional de Flora Silvestre Protegida; población de Cabo Cope señalada por su interés biogeográfico (aislada del resto de su área)',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (16,1,'Azufaifo','Ziziphus lotus','flora','Arbusto espinoso','Matorrales arborescentes de Ziziphus','Hábitat prioritario UE / Vulnerable','Arbusto espinoso de ambientes cálidos y secos, importante para refugio de fauna y estructura del paisaje.','Ramas en zigzag; Espinas visibles; Porte almohadillado','Primavera a otoño','https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/Ziziphus_lotus_%28fruit%29.jpg/640px-Ziziphus_lotus_%28fruit%29.jpg',37.509900,-1.463100,4,0,'Directiva Hábitats 92/43/CEE, hábitat prioritario 5220*; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable)','Tracheophyta','Magnoliopsida','Rosales','Rhamnaceae','Ziziphus','NE (no evaluada a nivel global)','Incluida en la Lista Roja de la Flora Vascular Española 2008 (categoría exacta pendiente de confirmar en listaroja.conservacionvegetal.org)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (17,1,'Cornical','Periploca angustifolia','flora','Arbusto iberoafricano','Matorral termófilo','Vulnerable','Arbusto característico de zonas cálidas del sureste ibérico, con gran interés biogeográfico. Forma los \'cornicales\', matorrales dominantes en laderas silicatadas del parque.','Hojas estrechas; Frutos alargados; Aspecto leñoso y abierto','Floración primaveral','https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Periploca_angustifolia_kz1.jpg/640px-Periploca_angustifolia_kz1.jpg',37.496700,-1.452800,3,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable)','Tracheophyta','Magnoliopsida','Gentianales','Apocynaceae','Periploca','NE (no evaluada a nivel global)','Pendiente de confirmar presencia y categoría en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (18,1,'Espino negro','Rhamnus lycioides subsp. borgiae','flora','Arbusto espinoso','Matorral litoral y laderas secas','Interés especial','Arbusto espinoso perennifolio típico del matorral mediterráneo costero, importante como refugio de fauna.','Ramas espinosas entrelazadas; Hojas pequeñas y coriáceas; Frutos globosos oscuros en otoño','Todo el año',NULL,37.500800,-1.440500,2,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; World Flora Online - Rhamnus lycioides (confirma Rhamnus hispanorum como sinónimo)','Tracheophyta','Magnoliopsida','Rosales','Rhamnaceae','Rhamnus','NE (no evaluada a nivel global)','No confirmada presencia en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (citada como Rhamnus hispanorum)',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (19,1,'Acebuche','Olea europaea var. sylvestris','flora','Árbol o arbusto','Matorral litoral y laderas secas','Interés botánico / aprovechamiento regulado','Forma silvestre del olivo, presente en los matorrales costeros mejor conservados del parque.','Hojas pequeñas grisáceas; Porte arbustivo denso y espinoso en ejemplares jóvenes; Frutos pequeños (acebuchinas)','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Olea_europaea_var._sylvestris_-_Acebuche.JPG',37.499500,-1.442000,2,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Lamiales','Oleaceae','Olea','LC','No catalogada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa (poblaciones silvestres)',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (20,1,'Margarita de mar','Asteriscus maritimus','flora','Planta litoral','Playas y dunas fósiles del litoral','Interés botánico','Pequeña planta almohadillada de flores amarillas, característica de roquedos y acantilados costeros.','Flores amarillas tipo margarita; Hojas carnosas grisáceas; Forma cojinetes sobre roca litoral','Todo el año, floración prolongada','https://commons.wikimedia.org/wiki/Special:FilePath/Asteriscus_maritimus-IMG_6052.jpg',37.486500,-1.469500,2,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Asteriscus','NE (no evaluada a nivel global)','No catalogada en la Lista Roja de la Flora Vascular Española 2008','No incluida en el Catálogo Regional de Flora Silvestre Protegida',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (21,1,'Albardín','Lygeum spartum','flora','Gramínea','Saladar y albardinal de la marina de Cope','Interés botánico','Gramínea perenne que forma el albardinal, comunidad vegetal característica de los suelos salinos de la marina de Cope.','Hojas rígidas y punzantes enrolladas; Inflorescencia envuelta en brácteas; Forma matas aisladas en suelo salino','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum_Closeup_12July2009_LagunadelaMata.jpg',37.472000,-1.483000,3,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Liliopsida','Poales','Poaceae','Lygeum','LC','No catalogada en la Lista Roja de la Flora Vascular Española 2008','No incluida en el Catálogo Regional de Flora Silvestre Protegida',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (22,1,'Cambrón','Lycium intricatum','flora','Arbusto espinoso','Matorral halófilo de la marina de Cope','Interés especial','Arbusto espinoso de suelos salinos y semiáridos, propio de los matorrales costeros de la marina de Cope.','Ramas muy ramificadas y espinosas; Hojas pequeñas y carnosas; Frutos rojos pequeños','Todo el año','Img/species/lycium-intricatum.jpg',37.473500,-1.479500,3,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre; Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Solanales','Solanaceae','Lycium','NE (no evaluada a nivel global)','No confirmada presencia en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (23,1,'Chumberillo de lobo','Caralluma europaea','flora','Planta suculenta','Matorral halonitrófilo costero','Vulnerable / En Peligro (España)','Pequeña planta suculenta de aspecto cactiforme, catalogada En Peligro a nivel nacional y Vulnerable en la Región de Murcia.','Tallos carnosos angulosos sin espinas; Flores pequeñas de olor desagradable; Muy localizada y difícil de encontrar','Verano y otoño (floración)','Img/species/caralluma-europaea.jpg',37.478000,-1.468000,5,1,'Lista Roja de la Flora Vascular Española 2008; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; Wikipedia; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable); Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Gentianales','Apocynaceae','Caralluma','NE (no evaluada a nivel global; distribución principal fuera de Europa, en el norte de África)','Lista Roja de la Flora Vascular Española 2008: EN (En Peligro), criterio B1ab(i,iii,iv,v)c(ii,iii,iv)+2ab(i,iii,iv,v)c(ii,iii,iv)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (24,1,'Centaurio de Rigual','Centaurium rigualii','flora','Planta herbácea endémica','Saladar y albardinal de la marina de Cope','Estatus taxonómico dudoso - en revisión','Planta herbácea citada como endemismo del sureste ibérico en fuentes de divulgación, aunque su validez taxonómica actual es objeto de debate.','Porte herbáceo bajo; Flores rosadas en pequeños grupos; Ligada a suelos salinos poco alterados','Primavera',NULL,37.470500,-1.485500,5,1,'Referencias de divulgación (a contrastar); Wikipedia','Tracheophyta','Magnoliopsida','Gentianales','Gentianaceae','Centaurium','NE','Excluida del Catálogo Nacional de Especies Amenazadas (CNEA) desde el año 2000 por dudas sobre su validez taxonómica','Pendiente de confirmar en el Catálogo Regional vigente','REVISAR: fuentes recientes indican que Centaurium rigualii fue excluida del Catálogo Nacional de Especies Amenazadas en 2000 por problemas de validez taxonómica (posible sinónimo de otro Centaurium). No se ha podido confirmar su presencia documentada específicamente en Cabo Cope con una fuente primaria fiable dentro de esta sesión. Recomendable verificar con un botánico antes de mantenerla en el catálogo definitivo.','2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (25,1,'Ajo de flor oscura','Allium melananthum','flora','Planta bulbosa','Espartales de la marina de Cope','Vulnerable','Ajo silvestre de flores muy oscuras, abundante en los espartales de la Marina de Cope; una de las especies más notables del área por su rareza.','Flores de color muy oscuro, casi negro; Crece entre espartales (Lygeum/Stipa); Floración llamativa a finales de primavera','Primavera','Img/species/allium-melananthum.jpg',37.475000,-1.478000,5,1,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable); nombre común alternativo \"ajo de flor negra\" según el PORN; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Liliopsida','Asparagales','Amaryllidaceae','Allium','NE (no evaluada a nivel global)','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (26,1,'Anabasis','Anabasis hispanica','flora','Planta suculenta halófila','Saladar y albardinal de la marina de Cope','Interés especial','Pequeña planta suculenta de suelos salinos, propia de los saladares de la Marina de Cope.','Tallos articulados suculentos; Aspecto de matorral bajo y compacto; Suelos salinos y yesosos','Verano-otoño',NULL,37.471500,-1.484000,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Caryophyllales','Amaranthaceae','Anabasis','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie poco conocida fuera de círculos botánicos especializados; confirmar identificación en campo por su similitud con otras quenopodiáceas suculentas.','2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (27,1,'Salsola','Salsola papillosa','flora','Planta halófila','Saladar y albardinal de la marina de Cope','Vulnerable','Quenopodiácea halófila de distribución muy restringida, catalogada Vulnerable en la Región de Murcia; citada como \'patagusanos\'.','Aspecto de matorral bajo grisáceo; Ligada a suelos salinos costeros; Muy localizada','Verano-otoño','Img/species/salsola-papillosa.jpg',37.469800,-1.486000,5,1,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable); Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Caryophyllales','Amaranthaceae','Salsola','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (28,1,'Espartilla de Persia','Enneapogon persicus','flora','Gramínea','Litosuelos cálidos del piso termomediterráneo','En peligro de extinción (Murcia) / En Peligro Crítico (España)','Gramínea perenne en penacho de litosuelos cálidos, catalogada En Peligro Crítico a nivel nacional por su rareza y distribución marginal en la península.','Forma matas densas de 10-50 cm; Tallos ligeramente pubescentes; Litosuelos cálidos semiáridos','Verano',NULL,37.513500,-1.449800,5,1,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Lista Roja de la Flora Vascular Española 2008 (floraprotegida.es); Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría En peligro de extinción)','Tracheophyta','Liliopsida','Poales','Poaceae','Enneapogon','NE (no evaluada a nivel global; especie de amplia distribución en Asia y África, rara en el extremo de su área ibérica)','Lista Roja de la Flora Vascular Española 2008: CR (En Peligro Crítico)','Catálogo Regional de Flora Silvestre Protegida de Murcia: En peligro de extinción',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (29,1,'Lechuguilla lanosa','Launaea lanifera','flora','Planta herbácea','Matorral árido y bordes de rambla','Interés especial','Planta herbácea perenne de aspecto lanoso, propia de ambientes áridos del sureste ibérico.','Pelosidad blanquecina y lanosa; Hojas en roseta basal; Ambientes áridos y pedregosos','Primavera-verano',NULL,37.512000,-1.452000,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Launaea','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (30,1,'Siempreviva insigne','Limonium insigne','flora','Planta litoral','Saladar y acantilados de la marina de Cope','Interés especial / aprovechamiento regulado','Siempreviva litoral que tapiza de color los saladares y zonas afectadas por la brisa marina a finales de primavera.','Flores lilas-azuladas en panícula; Hojas basales coriáceas; Saladares y roquedos costeros','Final de primavera','Img/species/limonium-insigne.jpg',37.489500,-1.473500,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Caryophyllales','Plumbaginaceae','Limonium','NE (no evaluada a nivel global; género con numerosos microendemismos ibéricos)','No localizada en la Lista Roja de la Flora Vascular Española 2008 con este nombre (pendiente de confirmar sinonimia)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial; aprovechamiento sujeto a autorización previa','El género Limonium tiene una taxonomía muy compleja con numerosos microendemismos; confirmar la identificación exacta de la población de Cabo Cope frente a especies afines (L. lobatum, L. cossonianum).','2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (31,1,'Cuerno de cabra','Notoceras bicorne','flora','Planta herbácea','Matorral árido y claros de vegetación','Interés especial','Crucífera muy escasa en el continente europeo, de flores pequeñas y fruto característico curvado.','Fruto en forma de cuerno curvado; Planta anual de pequeño tamaño; Claros de matorral árido','Primavera','Img/species/notoceras-bicorne.jpg',37.516500,-1.443500,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Brassicales','Brassicaceae','Notoceras','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (32,1,'Taray','Tamarix africana','flora','Árbol o arbusto','Saladar junto a la playa del Sombrerico','Interés especial','Arbusto o arbolillo que forma los bosquetes de taray de mayor biomasa de la zona, como el rodal junto a la playa del Sombrerico.','Ramas finas y flexibles; Flores rosadas en espigas; Forma bosquetes junto a saladares','Primavera-verano','https://commons.wikimedia.org/wiki/Special:FilePath/T._africana-1.JPG',37.474000,-1.478000,3,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Caryophyllales','Tamaricaceae','Tamarix','LC','No catalogada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (citado como Tamarix sp. pl.)',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (33,1,'Teucrio de Freyn','Teucrium freynii','flora','Planta aromática','Ramblas y cerros carbonatados','Interés especial','Labiada de distribución restringida, ligada a ambientes rocosos y de rambla del sureste ibérico.','Hojas aromáticas de labiada; Porte arbustivo bajo; Ambientes rocosos y ramblas','Primavera-verano','Img/species/teucrium-freynii.jpg',37.494500,-1.459500,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Teucrium','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (34,1,'Zamarrilla lanuda','Teucrium lanigerum','flora','Planta aromática','Cerros carbonatados','Interés especial','Una de las plantas más vistosas de la zona, de porte lanoso y flores llamativas, más abundante en cerros carbonatados.','Aspecto lanoso y plateado; Flores vistosas; Más abundante en sustratos carbonatados','Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_lanigerum_kz01.jpg',37.503000,-1.445500,4,1,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Teucrium','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (35,1,'Arto','Maytenus senegalensis subsp. europaea','flora','Arbusto espinoso','Matorral litoral y laderas secas','Vulnerable','Arbusto espinoso iberoafricano citado por su nombre común (\'arto\') entre los matorrales costeros del parque.','Ramas espinosas muy ramificadas; Hojas pequeñas coriáceas; Matorral costero denso','Todo el año','Img/species/maytenus-senegalensis-europaea.jpg',37.501000,-1.436800,3,0,'Región de Murcia Digital (CARM) - Flora de Cabo Cope y Puntas de Calnegre (mención por nombre común \'arto\'); El Medio Natural en Cartagena (urbanismo.cartagena.es), ficha \'Arto - Maytenus senegalensis subsp. europaea\'; Documento previo del PORN de Calnegre y Cabo Cope (CARM, 2021) - Catálogo Regional de Flora Silvestre Protegida (confirma categoría Vulnerable); Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Celastrales','Celastraceae','Maytenus','NE','Presente en el listado nacional de la Lista Roja de la Flora Vascular Española 2008 (categoría exacta pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (36,1,'Rabogato','Sideritis ibanyezii','flora','Planta aromática','Cerros carbonatados','Aprovechamiento regulado','Labiada aromática más abundante sobre sustratos carbonatados, citada por su nombre común \'rabogato\'.','Aspecto de matorral aromático bajo; Más abundante en sustrato carbonatado; Flores amarillentas en espiga','Primavera-verano',NULL,37.504500,-1.447500,3,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Sideritis','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 con este nombre','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (37,1,'Lentisco','Pistacia lentiscus','flora','Arbusto','Matorral mediterráneo litoral','Aprovechamiento regulado','Arbusto perennifolio muy común del matorral mediterráneo, con frutos apreciados por la fauna.','Hojas compuestas paripinnadas; Frutos en racimo rojos a negros; Resinoso y aromático al frotar','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus_g1.jpg',37.506200,-1.451200,1,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Sapindales','Anacardiaceae','Pistacia','LC','No catalogada (especie común mediterránea)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (38,1,'Pino carrasco','Pinus halepensis','flora','Árbol','Laderas y cerros del interior del parque','Aprovechamiento regulado','Conífera mediterránea de amplia distribución, presente en laderas y zonas de repoblación del interior del parque.','Copa irregular y abierta; Piñas asimétricas persistentes; Corteza rojiza agrietada','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Pinus_halepensis_2601.JPG',37.508300,-1.439800,1,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Pinopsida','Pinales','Pinaceae','Pinus','LC','No catalogada (especie forestal común)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa',NULL,'2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (39,1,'Tomillo de invierno','Thymus hyemalis','flora','Planta aromática','Tomillares sobre sustrato carbonatado','Aprovechamiento regulado','Tomillo endémico del sureste ibérico, característico de los tomillares sobre sustratos carbonatados del parque.','Matas bajas y aromáticas; Hojas pequeñas y estrechas; Sustratos carbonatados','Todo el año, floración primaveral','https://commons.wikimedia.org/wiki/Special:FilePath/Thymus_hyemalis_subsp._hyemalis_kz01.jpg',37.510800,-1.452500,2,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Thymus','NE','Una subespecie afín (Thymus hyemalis subsp. millefloris) figura en la Lista Roja de la Flora Vascular Española 2008; confirmar si aplica a la población del parque','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa','Existe una subespecie (millefloris) con presencia confirmada en la Lista Roja nacional; verificar a qué subespecie/población corresponden los ejemplares de Cabo Cope.','2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (40,1,'Alcaparra','Capparis sicula subsp. sicula','flora','Arbusto','Roquedos y muros del matorral litoral','Aprovechamiento regulado','Arbusto trepador o rastrero de roquedos, conocido por sus botones florales comestibles (alcaparras).','Hojas redondeadas y carnosas; Flores blancas vistosas de corta duración; Roquedos y taludes soleados','Verano',NULL,37.497800,-1.446000,2,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Magnoliopsida','Brassicales','Capparaceae','Capparis','NE','No catalogada en la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa',NULL,'2026-07-14 10:10:36','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (41,1,'Azucena de mar','Pancratium maritimum','flora','Planta bulbosa litoral','Dunas y playas del litoral','Aprovechamiento regulado','Bulbosa litoral de grandes flores blancas y aromáticas, propia de playas y dunas bien conservadas.','Flores blancas grandes y aromáticas; Hojas glaucas en roseta; Dunas y arenales costeros','Verano','https://commons.wikimedia.org/wiki/Special:FilePath/Pancratium_maritimum_-_Sea_Daffodil_12.jpg',37.541000,-1.400500,3,1,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia','Tracheophyta','Liliopsida','Asparagales','Amaryllidaceae','Pancratium','LC','No catalogada en la Lista Roja de la Flora Vascular Española 2008 (especie común pero sensible a la degradación de playas)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa','Reclasificada al hábitat oficial 2110 (dunas móviles embrionarias) por ser una especie característica de dunas costeras; esta asignación es una inferencia ecológica mía, ya que ni el Plan de Gestión del LIC Cabo Cope ni el Anexo I del PORN citan expresamente Pancratium maritimum entre las especies indicadoras de esa asociación (que mencionan Elymus farctus y Sporobolus pungens). Confirmar si procede.','2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (42,1,'Coloquíntida','Citrullus colocynthis','flora','Planta rastrera','Ramblas y zonas incultas','No catalogada, citada por su rareza','Cucurbitácea rastrera de frutos parecidos a pequeños melones, citada por su rareza en ramblas y zonas incultas de la Marina de Cope.','Frutos redondos tipo melón pequeño; Planta rastrera en ramblas; Zonas incultas y bordes de cultivo','Verano-otoño','Img/species/citrullus-colocynthis.jpg',37.492500,-1.457000,4,0,'Alcaraz Ariza, F.J. \'La Marina de Cope: ¿los últimos días de un paraíso botánico?\', Eubacteria nº5, Universidad de Murcia; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Cucurbitales','Cucurbitaceae','Citrullus','NE','No catalogada en la Lista Roja de la Flora Vascular Española 2008','No incluida en el Catálogo Regional de Flora Silvestre Protegida','No figura en ninguna de las tres categorías del Catálogo Regional (Decreto 50/2003); se incluye únicamente por citarse expresamente como notable/rara en la fuente de la Marina de Cope.','2026-07-14 10:10:36','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (64,1,'Cardo amarillo de roca','Centaurea saxicola','flora','Hierba de roquedo','Roquedos y fisuras calcáreas costeras','Vulnerable','Herbácea rupícola de fisuras de roquedos calcáreos costeros, integrante junto a Lafuentea rotundifolia de la asociación Lafuenteo rotundifoliae-Centaureetum saxicolae (721134), propia del hábitat de interés comunitario 8210.','Vive en grietas de roquedos calcáreos; Capítulos florales amarillos; Comparte hábitat con Lafuentea rotundifolia','Floración primaveral','https://commons.wikimedia.org/wiki/Special:FilePath/Centaurea_saxicola2.jpg',37.495500,-1.458500,4,0,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, Consejería de Agua, Agricultura, Ganadería, Pesca y Medio Ambiente, 2021) - Catálogo Regional de Flora Silvestre Protegida','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Centaurea','NE','Pendiente de contrastar con la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable','Especie añadida a partir del PORN; falta contrastar su distribución exacta dentro del parque y su presencia en la Lista Roja de la Flora Vascular Española 2008.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (65,1,'Orejilla de roca','Lafuentea rotundifolia','flora','Hierba de roquedo','Roquedos y fisuras calcáreas costeras','Vulnerable','Herbácea rupícola endémica del sureste ibérico, integrante junto a Centaurea saxicola de la asociación Lafuenteo rotundifoliae-Centaureetum saxicolae (721134), propia del hábitat de interés comunitario 8210.','Vive en fisuras de roquedos calcáreos; Hojas redondeadas; Comparte hábitat con Centaurea saxicola','Floración primaveral','Img/species/lafuentea-rotundifolia.jpg',37.494000,-1.461000,4,0,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, Consejería de Agua, Agricultura, Ganadería, Pesca y Medio Ambiente, 2021) - Catálogo Regional de Flora Silvestre Protegida; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Lamiales','Plantaginaceae','Lafuentea','NE','Pendiente de contrastar con la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable','Especie añadida a partir del PORN; falta contrastar su distribución exacta dentro del parque y su presencia en la Lista Roja de la Flora Vascular Española 2008.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (66,1,'Senecio flavus','Senecio flavus','flora','Hierba','Sin asociación de hábitat especificada en el PORN','Vulnerable','Especie protegida citada en el Catálogo Regional de Flora Silvestre Protegida para Calnegre y Cabo Cope; el PORN no documenta un nombre común ni una asociación de hábitat concreta dentro del parque.','Sin datos de campo documentados en el PORN','Sin datos','Img/species/senecio-flavus.jpg',37.501000,-1.445000,4,0,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, Consejería de Agua, Agricultura, Ganadería, Pesca y Medio Ambiente, 2021) - Catálogo Regional de Flora Silvestre Protegida; Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Senecio','NE','Pendiente de contrastar con la Lista Roja de la Flora Vascular Española 2008','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable','Sin hábitat, ubicación ni nombre común documentados en el PORN; falta confirmar en campo su localización exacta dentro del parque.','2026-07-14 10:10:37','2026-07-14 22:45:59');
