INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (84,1,'Culebra bastarda','Malpolon monspessulanus','fauna','Reptil','Matorral litoral y laderas secas','Interés especial','La culebra de mayor tamaño de la región, propia de matorral mediterráneo y zonas abiertas soleadas.','Gran tamaño (puede superar los 2 m); Levanta la cabeza cuando se siente amenazada; Activa de día en horas templadas','Primavera a otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Western_Montpellier_Snake_(Malpolon_monspessulanus).jpg',37.505000,-1.444000,3,0,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, Consejería de Agua, Agricultura, Ganadería, Pesca y Medio Ambiente, 2021)','Chordata','Reptilia','Squamata','Lamprophiidae','Malpolon','LC','LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)','Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial','El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (85,1,'Lagartija colirroja','Acanthodactylus erythrurus','fauna','Reptil','Matorral litoral y laderas secas','Interés especial','Lacértido de zonas arenosas y matorral abierto, con la cola de tono rojizo característico en los juveniles.','Cola rojiza en ejemplares jóvenes; Ligada a suelos sueltos y arenosos; Muy rápida y esquiva','Primavera a otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Red-tailed_Spiny-footed_Lizard_(Acanthodactylus_erythrurus)_(36541577786).jpg',37.506000,-1.442000,3,0,'Documento previo del PORN de Calnegre y Cabo Cope (CARM, Consejería de Agua, Agricultura, Ganadería, Pesca y Medio Ambiente, 2021)','Chordata','Reptilia','Squamata','Lacertidae','Acanthodactylus','LC','LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)','Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial','El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (95,1,'Palmito','Chamaerops humilis','flora','Palmera','Sabinar y matorral termomediterráneo','Interés especial','Única palmera autóctona de Europa continental, elemento termófilo característico del sabinar de Cabo Cope, donde acompaña a la sabina negral en la asociación Chamaeropo humilis-Juniperetum phoeniceae.','Hojas en abanico con peciolo espinoso; Porte arbustivo en mata; Elemento termófilo del sabinar','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Chamaerops_humilis_001.JPG',37.499800,-1.437800,3,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Liliopsida','Arecales','Arecaceae','Chamaerops','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; el hábitat se apoya en la asociación fitosociológica citada por las fuentes oficiales del parque. Coordenadas representativas, pendientes de precisar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (96,1,'Cinomorio','Cynomorium coccineum','flora','Planta parásita','Saladares y matorrales halonitrófilos','Interés especial','Planta parásita sin clorofila, de aspecto de maza rojiza, que crece sobre las raíces de quenopodiáceas halófilas de los saladares y estepas salinas.','Inflorescencia carnosa rojo-oscura en maza; Sin hojas verdes (parásita); Aparece sobre raíces de plantas halófilas','Primavera','Img/species/cynomorium-coccineum.jpg',37.474000,-1.480500,5,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003); Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Saxifragales','Cynomoriaceae','Cynomorium','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (97,1,'Eragrostis','Eragrostis papposa','flora','Gramínea','Pastizales de la subestepa de gramíneas','Interés especial','Pequeña gramínea de los pastizales secos y litosuelos cálidos, componente de la subestepa de gramíneas del piso termomediterráneo.','Panícula abierta y difusa; Mata de pequeño porte; Litosuelos secos y soleados','Verano',NULL,37.507800,-1.440500,4,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Liliopsida','Poales','Poaceae','Eragrostis','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (98,1,'Erodio','Erodium sanguis-christi','flora','Hierba anual','Litosuelos y pastizales abiertos','Interés especial','Pequeña geraniácea anual de suelos abiertos y pedregosos, de floración temprana en el piso termomediterráneo semiárido.','Flores rosadas pequeñas; Fruto con pico alargado característico de Erodium; Anual de suelos pedregosos','Primavera',NULL,37.508200,-1.441200,4,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Geraniales','Geraniaceae','Erodium','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (99,1,'Cantueso dentado','Lavandula dentata','flora','Mata aromática','Tomillares y matorral termomediterráneo','Interés especial','Lavanda de hojas dentadas, aromática, propia de tomillares y matorrales secos y soleados del sureste ibérico.','Hojas estrechas con margen dentado; Espiga floral violácea con penacho; Muy aromática','Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Lavandula-dentata.JPG',37.505200,-1.441500,3,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Lavandula','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (100,1,'Alhucema','Lavandula multifida','flora','Mata aromática','Matorral semiárido y bordes soleados','Interés especial','Lavanda de hojas muy divididas (bipinnadas), termófila, frecuente en matorrales abiertos y bordes soleados de la marina de Cope.','Hojas finamente divididas (bipinnadas); Flores azul-violáceas; Aroma intenso','Primavera a otoño','Img/species/lavandula-multifida.jpg',37.504500,-1.440800,3,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003); Foto: florasilvestre.es (galería de flora del sureste ibérico)','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Lavandula','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (101,1,'Leucanto litoral','Leucanthemum decipiens','flora','Hierba de roquedo','Roquedos y acantilados costeros','Interés especial','Margarita perenne de roquedos y acantilados litorales, integrante de las comunidades rupícolas costeras del parque.','Capítulos con lígulas blancas y centro amarillo; Vive en fisuras y repisas rocosas; Ambientes rupícolas costeros','Primavera',NULL,37.494800,-1.458800,4,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Leucanthemum','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (102,1,'Siempreviva de Cosson','Limonium cossonianum','flora','Planta halófila','Acantilados y saladares costeros','Interés especial','Siempreviva dominante de los acantilados litorales del parque, especie característica de la asociación Limonio cossoniani-Lycietum intricati (hábitat 1240) y presente también en saladares.','Roseta basal de hojas espatuladas; Panículas de flores violáceas persistentes; Domina los acantilados costeros','Verano','https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_cossonianum_kz01.jpg',37.487200,-1.471200,3,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Caryophyllales','Plumbaginaceae','Limonium','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; el hábitat se apoya en la asociación fitosociológica citada por las fuentes oficiales del parque. Coordenadas representativas, pendientes de precisar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (103,1,'Bayón','Osyris lanceolata','flora','Arbusto hemiparásito','Sabinar y matorral termófilo','Interés especial','Arbusto perennifolio hemiparásito, elemento termófilo de gran interés de conservación que acompaña a la sabina negra en el sabinar de Cabo Cope.','Arbusto de hojas lanceoladas coriáceas; Hemiparásito de raíces de otras plantas; Frutos carnosos rojizos','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Osyris_lanceolata76.JPG',37.500300,-1.438000,3,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Santalales','Santalaceae','Osyris','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; el hábitat se apoya en la asociación fitosociológica citada por las fuentes oficiales del parque. Coordenadas representativas, pendientes de precisar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (104,1,'Coscoja','Quercus coccifera','flora','Arbusto esclerófilo','Matorral esclerófilo y sabinar','Interés especial','Arbusto esclerófilo de hoja perenne y espinosa, integrante del matorral mediterráneo denso y de las orlas del sabinar.','Hojas coriáceas con margen espinoso; Bellota con cúpula de escamas punzantes; Porte arbustivo denso','Todo el año','https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_coccifera_1.JPG',37.500800,-1.439200,2,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Fagales','Fagaceae','Quercus','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (105,1,'Zapatito de la Virgen','Sarcocapnos enneaphylla subsp. saetabensis','flora','Hierba de roquedo','Extraplomos y roquedos calcáreos','Interés especial','Pequeña planta rupícola de extraplomos y oquedades de roquedos calcáreos, integrante de la asociación Resedo paui-Sarcocapnetum saetabensis del hábitat 8210.','Cuelga de extraplomos y techos rocosos; Flores blanco-rosadas con espolón; Hojas divididas glaucas','Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Sarcocapnos_enneaphylla_saetabensis.jpg',37.494200,-1.459200,4,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Ranunculales','Papaveraceae','Sarcocapnos','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; el hábitat se apoya en la asociación fitosociológica citada por las fuentes oficiales del parque. Coordenadas representativas, pendientes de precisar en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (106,1,'Serrátula','Serratula mucronata','flora','Hierba','Matorral y pastizales secos','Interés especial','Compuesta perenne de matorrales y pastizales secos del piso termomediterráneo, incluida en el Catálogo Regional por su interés.','Capítulos sin lígulas, de tonos purpúreos; Hojas con margen mucronado; Matorrales y pastizales secos','Verano y otoño',NULL,37.506500,-1.441800,4,0,'Anexo I del proyecto de PORN del Parque Regional costero-litoral de Cabo Cope (ANSE / CARM) - Catálogo de Flora Silvestre Protegida (Decreto 50/2003)','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Serratula','NE','No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)','Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial','Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (110,1,'Grama de mar','Elymus farctus','flora','Gramínea psammófila','Dunas móviles embrionarias','Preocupación menor','Gramínea rizomatosa y glauca que entrelaza la arena con sus largos rizomas y levanta las primeras dunas embrionarias; especie dominante de este hábitat en el Mediterráneo.','Rizomas largos que traban la arena; Hojas glaucas y rígidas; Espiga que se fragmenta al madurar','Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Elymus_farctus_kz14.jpg',37.466650,-1.473600,2,0,'Especie dominante/característica del hábitat de interés comunitario 2110 (Dunas móviles embrionarias) según las Bases ecológicas preliminares para la conservación de los tipos de hábitat de interés comunitario en España (VVAA, Ministerio de Medio Ambiente, Medio Rural y Marino, 2009) y la ficha del hábitat (Murcianatural, CARM); presencia en el litoral de la Región de Murcia confirmada en la flora regional. Sinónimos: Elytrigia juncea, Thinopyrum junceum.','Tracheophyta','Liliopsida','Poales','Poaceae','Elymus','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común de amplia distribución litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); citada como especie característica de este hábitat en el litoral murciano','Añadida como especie característica del hábitat 2110, documentada en el litoral de la Región de Murcia. Su presencia concreta en el parque se infiere del hábitat cartografiado y queda pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (111,1,'Juncia marina','Cyperus capitatus','flora','Ciperácea dunar','Dunas móviles embrionarias','Preocupación menor','Ciperácea de arenales litorales, con tallos de sección triangular y cabezuela globosa; especie característica de las dunas embrionarias mediterráneas.','Tallo de sección triangular; Inflorescencia en cabezuela apretada; Crece sobre arena suelta','Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Teguise_Tao_-_Avenida_Bencomo-LZ20_-_Cyperus_capitatus_01_ies.jpg',37.466550,-1.473450,3,0,'Especie característica del hábitat de interés comunitario 2110 (Dunas móviles embrionarias) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); presencia en el litoral de la Región de Murcia (p. ej. Calblanque) confirmada en el Herbari Virtual del Mediterrani Occidental (Univ. de les Illes Balears). Sinónimo: Cyperus kalli.','Tracheophyta','Liliopsida','Poales','Cyperaceae','Cyperus','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de este hábitat en el litoral murciano','Añadida como especie característica del hábitat 2110, documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
