INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (117,1,'Uña de gato','Sedum sediforme','flora','Crasulácea','Prados calcáreos del Alysso-Sedion albi','Preocupación menor','Crasulácea perenne de hojas suculentas puntiagudas y flores amarillo-verdosas, muy extendida por Murcia en repisas rocosas y prados calcáreos; especie característica del hábitat prioritario.','Hojas carnosas puntiagudas; Inflorescencia amarillo pálido; Coloniza repisas y suelos esqueléticos','Verano','https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_sediforme-Orpin_de_Nice-201607032.jpg',37.427750,-1.486100,1,0,'Especie característica del hábitat prioritario de interés comunitario 6110* (Prados calcáreos cársticos o basófilos del Alysso-Sedion albi) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); extendida por toda la Región de Murcia (Flora Silvestre de Murcia; regmurcia.com, flora de roquedos).','Tracheophyta','Magnoliopsida','Saxifragales','Crassulaceae','Sedum','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de este hábitat, extendida por la Región','Añadida como especie característica del hábitat prioritario 6110*, extendida por la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
