INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (119,1,'Sedo de hojas gruesas','Sedum dasyphyllum','flora','Crasulácea','Prados calcáreos del Alysso-Sedion albi','Preocupación menor','Pequeña crasulácea glandulosa de hojas gruesas, glaucas y opuestas, que cuelga de grietas de roca termófilas; elemento con distribución murciano-almeriense en su cortejo.','Hojas gruesas glaucas y opuestas; Tacto glanduloso-pegajoso; Vive en grietas de roca','Verano','https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_dasyphyllum_(June_2010).jpg',37.427800,-1.486120,3,0,'Especie del cortejo característico del hábitat prioritario de interés comunitario 6110* (Alysso-Sedion albi) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural, CARM); Sedum dasyphyllum subsp. glanduliferum es un elemento de distribución murciano-almeriense; presencia en la Región de Murcia confirmada en la flora regional.','Tracheophyta','Magnoliopsida','Saxifragales','Crassulaceae','Sedum','No evaluada específicamente en la Lista Roja mundial de la UICN','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de roquedos y prados calcáreos de la Región','Añadida como especie del cortejo característico del hábitat prioritario 6110*, documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
