INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (121,1,'Amapola marina','Glaucium flavum','flora','Papaverácea de gravas','Ríos mediterráneos con Glaucium flavum','Preocupación menor','Amapola perenne glauca de grandes flores amarillas y cápsula muy larga, propia de gravas y cauces; es la especie que da nombre al hábitat 3250.','Flores amarillas grandes; Follaje glauco y lobulado; Fruto en cápsula muy larga','Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Glaucium_flavum_-_Orto_botanico_-_Rome,_Italy_-_DSC09962.jpg',37.500680,-1.478350,2,0,'Especie que da nombre y caracteriza el hábitat de interés comunitario 3250 (Ríos mediterráneos de caudal permanente con Glaucium flavum) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural / OISMA, CARM); presencia en cauces y gravas de la Región de Murcia confirmada en la flora regional.','Tracheophyta','Magnoliopsida','Ranunculales','Papaveraceae','Glaucium','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de gravas y cauces de la Región','Añadida como especie característica del hábitat 3250, documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (122,1,'Mata del vizque','Andryala ragusina','flora','Compuesta de rambla','Ríos mediterráneos con Glaucium flavum','Preocupación menor','Compuesta blanco-tomentosa de capítulos amarillos, pionera de gravas y arenas de rambla; extendida por toda la Región de Murcia.','Aspecto blanco-lanoso; Capítulos amarillos; Coloniza gravas removidas de cauce','Primavera a otoño','https://commons.wikimedia.org/wiki/Special:FilePath/114Andryala_ragusina.JPG',37.500580,-1.478250,1,0,'Especie característica de las gravas fluviales del hábitat de interés comunitario 3250 (Ríos mediterráneos con Glaucium flavum) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural / OISMA, CARM); extendida por la Región de Murcia (Flora Silvestre de Murcia).','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Andryala','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); extendida por la Región','Añadida como especie característica del hábitat 3250, extendida por la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (123,1,'Escrofularia de perro','Scrophularia canina','flora','Escrofulariácea de gravas','Ríos mediterráneos con Glaucium flavum','Preocupación menor','Escrofularia perenne de tallos ramosos y flores diminutas pardo-purpúreas, típica de gravas fluviales y cauces pedregosos.','Hojas divididas; Flores diminutas pardo-rojizas; Crece en gravas de cauce','Primavera y verano',NULL,37.500720,-1.478420,2,0,'Especie característica de las gravas fluviales del hábitat de interés comunitario 3250 (Ríos mediterráneos con Glaucium flavum) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural / OISMA, CARM); presencia en cauces de la Región de Murcia confirmada en la flora regional.','Tracheophyta','Magnoliopsida','Lamiales','Scrophulariaceae','Scrophularia','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); característica de cauces de la Región','Añadida como especie característica del hábitat 3250, documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (124,1,'Olivarda','Dittrichia viscosa','flora','Compuesta pionera','Ríos mediterráneos con Glaucium flavum','Preocupación menor','Compuesta pegajosa y aromática de flores amarillas, muy pionera, que coloniza cauces pedregosos, gravas y suelos removidos.','Follaje viscoso y aromático; Floración amarilla otoñal; Muy pionera en gravas y bordes','Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Woody_Fleabane_(Olivarda)_(Dittrichia_viscosa)_-_Cartagena,_Spain_2024-02-05.jpg',37.500500,-1.478180,1,0,'Especie pionera de gravas y cauces del hábitat de interés comunitario 3250 (Ríos mediterráneos con Glaucium flavum) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y la ficha del hábitat (Murcianatural / OISMA, CARM); muy común en la Región de Murcia. Sinónimo: Inula viscosa.','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Dittrichia','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia (Decreto 50/2003); muy común en la Región','Añadida como especie pionera característica del hábitat 3250, muy común en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado, pendiente de confirmación en campo.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (125,1,'Sosa alacranera','Arthrocnemum macrostachyum','flora','Quenopodiácea halófila','Matorrales halófilos mediterráneos','No amenazada','Matecillo suculento de tallos articulados sin hojas visibles, dominante en los saladares costeros; forma manchas grisáceo-verdosas sobre suelos salinos.',NULL,'Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Arthrocnemum_macrostachyum_kz02.jpg',37.482150,-1.464250,1,0,'Especie característica del hábitat de interés comunitario 1420 (Matorrales halófilos mediterráneos y termoatlánticos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en los saladares de la Región de Murcia (Cabo Cope, Calarreona) confirmada en la ficha de Saladares de Región de Murcia Digital (regmurcia.com). Sinónimo: Arthrocaulon macrostachyum. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Caryophyllales','Amaranthaceae','Arthrocnemum','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de los saladares de la Región','Ficha básica: especie característica del hábitat 1420 documentada en los saladares de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
