INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (131,1,'Siempreviva de saladar','Limonium delicatulum','flora','Plumbaginácea halófila','Estepas salinas mediterráneas (Limonietalia)','No amenazada','Siempreviva perenne en roseta con panícula de florecillas violáceas, propia de los suelos salinos temporalmente húmedos del saladar; género que da nombre al orden Limonietalia.',NULL,'Verano',NULL,37.502050,-1.430100,2,0,'Especie característica del hábitat prioritario de interés comunitario 1510* (Estepas salinas mediterráneas, Limonietalia) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en los saladares de la Región de Murcia confirmada en la flora regional (Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Caryophyllales','Plumbaginaceae','Limonium','No evaluada específicamente en la Lista Roja mundial de la UICN','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de este hábitat en la Región','Ficha básica: especie característica del hábitat prioritario 1510* documentada en los saladares de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 11:59:22');
