INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (133,1,'Hinojo marino','Crithmum maritimum','flora','Umbelífera rupícola litoral','Acantilados mediterráneos con Limonium','No amenazada','Umbelífera carnosa y aromática de las rocas costeras batidas por el mar, con hojas divididas suculentas y umbelas amarillo-verdosas; crece en fisuras del acantilado.',NULL,'Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Criste_marine_(Crithmum_maritimum).JPG',37.423900,-1.494800,2,0,'Especie característica del hábitat de interés comunitario 1240 (Acantilados con vegetación de las costas mediterráneas con Limonium spp. endémicos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en el litoral rocoso de la Región de Murcia confirmada en la flora regional. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Apiales','Apiaceae','Crithmum','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica del litoral rocoso de la Región','Ficha básica: especie característica del hábitat 1240 documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (134,1,'Rugueta de mar','Cakile maritima','flora','Crucífera de playa','Vegetación anual sobre desechos marinos','No amenazada','Crucífera anual carnosa de flores lilas o blancas, pionera de la línea de arribazón donde se acumulan los restos orgánicos del mar en la playa alta.',NULL,'Primavera a otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Cakile_maritima_(flowers).jpg',37.466650,-1.473600,1,0,'Especie característica del hábitat de interés comunitario 1210 (Vegetación anual sobre desechos marinos acumulados) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en las playas de la Región de Murcia confirmada en la flora regional. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Brassicales','Brassicaceae','Cakile','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de las playas de la Región','Ficha básica: especie característica del hábitat 1210 documentada en las playas de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (135,1,'Barrilla pinchosa','Salsola kali','flora','Quenopodiácea de playa','Vegetación anual sobre desechos marinos','No amenazada','Hierba anual espinescente de la línea de arribazón y las arenas removidas, que al secarse rueda con el viento dispersando sus semillas.',NULL,'Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_kali_habito.jpg',37.466500,-1.473450,1,0,'Especie característica del hábitat de interés comunitario 1210 (Vegetación anual sobre desechos marinos acumulados) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en las playas de la Región de Murcia confirmada en la flora regional. Sinónimo: Kali turgidum. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Caryophyllales','Amaranthaceae','Salsola','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de las playas de la Región','Ficha básica: especie característica del hábitat 1210 documentada en las playas de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (136,1,'Acelga marina','Beta maritima','flora','Quenopodiácea de playa','Vegetación anual sobre desechos marinos','No amenazada','Hierba robusta de hojas carnosas brillantes, ancestro silvestre de la acelga y la remolacha, que crece en la línea de arribazón y suelos litorales algo nitrificados.',NULL,'Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Beta_vulgaris_maritima02.jpg',37.466720,-1.473750,1,0,'Especie característica del hábitat de interés comunitario 1210 (Vegetación anual sobre desechos marinos acumulados) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en el litoral de la Región de Murcia confirmada en la flora regional. Nombre completo: Beta vulgaris subsp. maritima. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Caryophyllales','Amaranthaceae','Beta','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica del litoral de la Región','Ficha básica: especie característica del hábitat 1210 documentada en el litoral de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (137,1,'Lastón','Brachypodium retusum','flora','Gramínea vivaz','Subestepa de gramíneas del Thero-Brachypodietea','No amenazada','Gramínea vivaz cespitosa que forma los lastonares, pastizal dominante en laderas y llanos secos del sureste; es la especie que estructura este hábitat prioritario.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_poblament_Canyelles.jpg',37.429300,-1.489700,1,0,'Especie estructural del hábitat prioritario de interés comunitario 6220* (Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea; asociación Teucrio pseudochamaepityos-Brachypodietum ramosi) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia, franja costera e interior (Región de Murcia Digital). Sinónimo: Brachypodium ramosum. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Brachypodium','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy frecuente en la Región','Ficha básica: especie estructural del hábitat prioritario 6220*, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (138,1,'Barba de chivo','Stipa capensis','flora','Gramínea anual','Subestepa de gramíneas del Thero-Brachypodietea','No amenazada','Gramínea anual con largas aristas plumosas que domina los pastizales terofíticos de los territorios semiáridos del sureste tras las lluvias.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_capensis.JPG',37.429180,-1.489550,1,0,'Especie característica del hábitat prioritario de interés comunitario 6220* (Thero-Brachypodietea; pastizales terofíticos semiáridos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; dominante en los pastizales semiáridos de la Región de Murcia y el sureste (Región de Murcia Digital). Sinónimo: Stipa retorta. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Stipa','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en los pastizales de la Región','Ficha básica: especie característica del hábitat prioritario 6220* documentada en el sureste y la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (139,1,'Cerrillo','Hyparrhenia hirta','flora','Gramínea vivaz','Subestepa de gramíneas del Thero-Brachypodietea','No amenazada','Gramínea vivaz que forma los cerrillares en ribazos, taludes y laderas soleadas, con inflorescencias pareadas y hojas ásperas.',NULL,'Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Hyparrhenia_hirta_20190521c.jpg',37.429420,-1.489450,1,0,'Especie característica del hábitat prioritario de interés comunitario 6220* (Thero-Brachypodietea; cerrillares) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia (Región de Murcia Digital). Sinónimo: Hyparrhenia sinaica. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Hyparrhenia','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del hábitat prioritario 6220* documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (140,1,'Zaragatona blanca','Plantago albicans','flora','Plantaginácea de pastizal','Subestepa de gramíneas del Thero-Brachypodietea','No amenazada','Plantago perenne blanco-tomentoso de hojas estrechas, propio de pastizales secos, ribazos y suelos margosos de los territorios semiáridos.',NULL,'Primavera',NULL,37.429100,-1.489800,1,0,'Especie característica de los pastizales del hábitat prioritario de interés comunitario 6220* (Thero-Brachypodietea) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia (Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Lamiales','Plantaginaceae','Plantago','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del hábitat prioritario 6220* documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (141,1,'Gamoncillo','Asphodelus fistulosus','flora','Asfodelácea de pastizal','Subestepa de gramíneas del Thero-Brachypodietea','No amenazada','Hierba perenne de hojas huecas y roseta basal con tallo florido de flores blanco-rosadas, frecuente en pastizales, eriales y bordes de camino de zonas secas.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Varita_de_San_Jos%C3%A9_(Asphodelus_fistulosus).jpg',37.429480,-1.489900,1,0,'Especie frecuente en los pastizales del hábitat prioritario de interés comunitario 6220* (Thero-Brachypodietea) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; común en la Región de Murcia (Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Asparagales','Asphodelaceae','Asphodelus','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); común en la Región','Ficha básica: especie frecuente del hábitat prioritario 6220* documentada en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (142,1,'Baladre','Nerium oleander','flora','Arbusto ribereño (adelfa)','Galerías y matorrales ribereños termomediterráneos','No amenazada','Arbusto siempreverde de hojas coriáceas lanceoladas y grandes flores rosadas, que forma adelfares en los cauces y ramblas de aguas intermitentes; toda la planta es tóxica.',NULL,'Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Nerium_oleander_(Oleandro).JPG',37.439500,-1.487350,2,0,'Especie característica del hábitat de interés comunitario 92D0 (Galerías y matorrales ribereños termomediterráneos, Nerio-Tamaricetea) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; forma los adelfares de las ramblas de la Región de Murcia (Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Gentianales','Apocynaceae','Nerium','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de las ramblas de la Región','Ficha básica: especie característica del hábitat 92D0 documentada en las ramblas de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (143,1,'Carrizo real','Saccharum ravennae','flora','Gramínea ribereña','Galerías y matorrales ribereños termomediterráneos','No amenazada','Gramínea robusta y cespitosa de hasta 2-3 m, con grandes panículas plumosas plateadas, propia de márgenes de cauce, ramblas y suelos húmedos algo salinos.',NULL,'Verano y otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Saccharum_ravennae_-_J._C._Raulston_Arboretum_-_DSC06214.JPG',37.439380,-1.487200,2,0,'Especie característica de los márgenes de cauce del hábitat de interés comunitario 92D0 (Galerías y matorrales ribereños termomediterráneos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; presencia en las ramblas de la Región de Murcia confirmada en la flora regional. Sinónimo: Tripidium ravennae, Erianthus ravennae. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Saccharum','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de las ramblas de la Región','Ficha básica: especie característica del hábitat 92D0 documentada en las ramblas de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (156,1,'Esparto','Stipa tenacissima','flora','Gramínea vivaz esteparia','Matorral termomediterráneo semiárido','No amenazada','Gramínea vivaz que forma los espartales o atochares, pastizal-matorral dominante en las laderas secas del sureste; su fibra se ha aprovechado tradicionalmente. Estructura buena parte del paisaje semiárido del parque.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_tenacissima.jpg',37.501300,-1.449600,1,0,'Especie estructural del matorral y pastizal semiárido (hábitat 5330 y espartales termomediterráneos) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; los espartales de la Marina de Cope se citan expresamente en la flora del parque (regmurcia.com). Sinónimo: Macrochloa tenacissima. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Stipa','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy frecuente en la Región','Ficha básica: especie estructural del matorral semiárido, muy frecuente en la Región de Murcia y en los espartales de la Marina de Cope. Presencia en el parque muy probable; pendiente de confirmación puntual y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (157,1,'Albaida','Anthyllis cytisoides','flora','Leguminosa arbustiva','Matorral termomediterráneo semiárido','No amenazada','Mata leguminosa blanco-tomentosa de flores amarillas en espiga, muy extendida en el matorral semiárido y los ribazos margosos del sureste; forma los albaidales.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG',37.501100,-1.449400,1,0,'Especie característica del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; muy extendida por la Región de Murcia (ficha de flora de regmurcia.com y Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Fabales','Fabaceae','Anthyllis','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy extendida por la Región','Ficha básica: especie característica del matorral semiárido, muy extendida por la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (158,1,'Aulaga','Launaea arborescens','flora','Compuesta espinosa','Matorral termomediterráneo semiárido','No amenazada','Matecillo intrincado y espinoso en forma de bola, con látex, de flores amarillas, propio de matorrales áridos, ribazos y suelos removidos del sureste; también llamada rascavieja.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Launaea_arborescens_kz21.jpg',37.500900,-1.449750,1,0,'Especie característica del matorral semiárido (hábitat 5330) y de los matorrales halo-nitrófilos (1430) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia (ficha de regmurcia.com). Sinónimo: Launaea spinosa. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Launaea','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (159,1,'Romero','Salvia rosmarinus','flora','Arbusto aromático','Matorral termomediterráneo semiárido','No amenazada','Arbusto aromático de hojas lineares revolutas y flores azuladas, muy común en el matorral calcícola mediterráneo; forma los romerales, a menudo con brezo y tomillos.',NULL,'Todo el año (máximo en invierno y primavera)','https://commons.wikimedia.org/wiki/Special:FilePath/Rosmarinus_officinalis_0001.JPG',37.501450,-1.449250,1,0,'Especie característica del matorral termomediterráneo (hábitat 5330; romerales del Rosmarino-Ericion) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; muy común en la Región de Murcia. Sinónimo: Rosmarinus officinalis. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Salvia','No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy común en la Región','Ficha básica: especie característica del matorral semiárido, muy común en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (160,1,'Canadillo','Ephedra fragilis','flora','Gnetófita arbustiva','Matorral termomediterráneo semiárido','No amenazada','Arbusto de tallos verdes articulados y colgantes, sin hojas visibles, que trepa o se apoya en otras matas; propio de matorrales secos, roquedos y sabinares del sureste. También llamado belcho.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Joint_Pine_(Ephedra_fragilis)_-_Cartagena,_Spain_2024-02-05_(01).jpg',37.426500,-1.487600,2,0,'Especie característica del matorral termomediterráneo semiárido (5330), sabinares (5210) y roquedos (8210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Gnetopsida','Ephedrales','Ephedraceae','Ephedra','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del matorral semiárido y roquedos, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (161,1,'Oroval','Withania frutescens','flora','Arbusto iberoafricano','Matorral termomediterráneo semiárido','Interés biogeográfico','Arbusto de hojas ovales algo carnosas y florecillas verdosas, iberoafricanismo de los matorrales más térmicos del sureste; refuerza el carácter africano de la flora de Cabo Cope.',NULL,'Primavera y otoño',NULL,37.501000,-1.463100,3,0,'Especie característica de los matorrales térmicos del sureste (hábitats 5330 y azufaifar 5220), iberoafricanismo, según las fichas de flora de la Región de Murcia (regmurcia.com, ficha Withania frutescens - Oroval) y las Bases ecológicas de la Red Natura 2000. Sinónimo: Withania frutescens (L.) Pauquy. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Solanales','Solanaceae','Withania','No evaluada específicamente en la Lista Roja mundial de la UICN','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); elemento iberoafricano característico del sureste árido','Ficha básica: iberoafricanismo característico de los matorrales térmicos del sureste, documentado en la Región de Murcia. Presencia en el parque inferida del hábitat y del carácter iberoafricano de su flora; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 11:59:22');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (162,1,'Esparraguera blanca','Asparagus albus','flora','Asparagácea espinosa','Matorral termomediterráneo semiárido','No amenazada','Mata espinosa de tallos blanquecinos y cladodios agrupados, que pierde la hoja en verano; frecuente en el matorral térmico, azufaifares y sabinares del sureste.',NULL,'Otoño','https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_albus_138.JPG',37.501200,-1.462950,1,0,'Especie característica del matorral termomediterráneo (5330) y del sotobosque de azufaifares (5220) y sabinares (5210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Asparagales','Asparagaceae','Asparagus','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del matorral térmico y azufaifares, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (163,1,'Manrubio negro','Ballota hirsuta','flora','Labiada arbustiva','Matorral termomediterráneo semiárido','No amenazada','Mata labiada grisáceo-tomentosa de olor fuerte, con flores rosado-purpúreas, frecuente en ribazos, cunetas y claros del matorral semiárido.',NULL,'Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Ballota_hirsuta_flowers.jpg',37.500850,-1.449550,1,0,'Especie característica del matorral y de los herbazales del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Ballota','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (164,1,'Mata pulguera','Phagnalon saxatile','flora','Compuesta rupícola','Matorral termomediterráneo semiárido','No amenazada','Matilla blanco-tomentosa de capítulos pardo-amarillentos secos, propia de roquedos, muros, taludes y claros pedregosos del matorral seco.',NULL,'Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Phagnalon_saxatile_kz02.jpg',37.426600,-1.487400,1,0,'Especie característica de los claros pedregosos y roquedos (hábitats 5330 y 8210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Sinónimo: Phagnalon rupestre s.l. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Asterales','Asteraceae','Phagnalon','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica de matorral y roquedos, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (165,1,'Zamarrilla','Teucrium capitatum','flora','Labiada de tomillar','Matorral termomediterráneo semiárido','No amenazada','Matilla labiada blanquecina de cabezuelas florales globosas blanco-cremosas, característica de tomillares y pastizales secos sobre suelos calizos.',NULL,'Primavera y verano','https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_capitatum_%2843995472764%29.jpg',37.500750,-1.449300,1,0,'Especie característica de los tomillares del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Sinónimo: Teucrium polium subsp. capitatum. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Lamiales','Lamiaceae','Teucrium','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica de los tomillares del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (166,1,'Fagonia','Fagonia cretica','flora','Cigofilácea iberoafricana','Matorral termomediterráneo semiárido','Interés biogeográfico','Pequeña mata algo espinosa de hojas trifoliadas y flores estrelladas violáceas, iberoafricanismo de suelos pedregosos áridos y roquedos térmicos del sureste.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Fagonia_cretica_01.JPG',37.426700,-1.487250,3,0,'Especie característica de los suelos pedregosos áridos y roquedos térmicos del sureste (hábitats 5330 y 8210), iberoafricanismo, según las fichas de flora de la Región de Murcia y las Bases ecológicas de la Red Natura 2000. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Zygophyllales','Zygophyllaceae','Fagonia','No evaluada específicamente en la Lista Roja mundial de la UICN','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); elemento iberoafricano del sureste árido','Ficha básica: iberoafricanismo característico de suelos áridos del sureste, documentado en la Región de Murcia. Presencia en el parque inferida del hábitat y del carácter iberoafricano de su flora; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (167,1,'Romero macho','Cistus clusii','flora','Jara (Cistácea)','Matorral termomediterráneo semiárido','No amenazada','Jara de hojas estrechas revolutas parecidas a las del romero y flores blancas, propia de matorrales secos y romerales sobre caliza; también llamada jaguarzo morisco.','Esta estepa se caracteriza por sus hojas lineales y estrechas, muy parecidas a las del romero, para diferenciarlos no hay más que oler las hojas y darnos cuenta que no tienen aroma. En flor no hay problema, ya que destacan sus grandes flores blancas.','Primavera','https://upload.wikimedia.org/wikipedia/commons/8/81/Cistus_clusii_kz05.jpg',37.500650,-1.449450,2,0,'Especie característica de los matorrales y romerales del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Malvales','Cistaceae','Cistus','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-15 00:11:34');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (168,1,'Jarilla de Almería','Helianthemum almeriense','flora','Jarilla (Cistácea)','Matorral termomediterráneo semiárido','No amenazada','Matilla de hojas grisáceo-tomentosas y flores amarillas o blanquecinas, característica de los tomillares y matorrales áridos del cuadrante sureste, sobre suelos margosos y pedregosos.',NULL,'Primavera','https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_almeriense_flor.jpg',37.500550,-1.449650,2,0,'Especie característica de los tomillares y matorrales áridos del sureste (hábitat 5330) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; propia del sureste ibérico y la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Magnoliopsida','Malvales','Cistaceae','Helianthemum','No evaluada específicamente en la Lista Roja mundial de la UICN','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); propia del sureste árido y la Región','Ficha básica: especie característica de los tomillares del sureste, propia de la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 22:45:59');
INSERT INTO `species` (`id`, `park_id`, `common_name`, `scientific_name`, `kingdom`, `family`, `primary_habitat`, `conservation_status`, `description`, `identification_tips`, `seasonality`, `image_url`, `latitude`, `longitude`, `rarity_score`, `is_featured`, `source`, `taxon_phylum`, `taxon_class`, `taxon_order`, `taxon_family`, `taxon_genus`, `iucn_global`, `spain_status`, `murcia_status`, `review_note`, `created_at`, `updated_at`) VALUES (169,1,'Melica menor','Melica minuta','flora','Gramínea rupícola','Pendientes rocosas calcícolas con vegetación casmofítica','No amenazada','Gramínea perenne cespitosa de panícula laxa, propia de fisuras y repisas de roquedos calizos y taludes pedregosos secos del ámbito mediterráneo.',NULL,'Primavera',NULL,37.426350,-1.487550,2,0,'Especie característica de los roquedos y pendientes rocosas calcícolas (hábitat 8210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.','Tracheophyta','Liliopsida','Poales','Poaceae','Melica','No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)','No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE','No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región','Ficha básica: especie característica de los roquedos calcáreos, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.','2026-07-14 10:10:37','2026-07-14 11:59:22');
